(function(root){'use strict';
const DAY=86400000,skills={listening:'Listening',speaking:'Speaking',reading:'Reading',writing:'Writing'},colors={listening:'#1469c7',speaking:'#8b4cb8',reading:'#18826b',writing:'#d27b18'};
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=n=>Number.isFinite(n)?n.toLocaleString('vi-VN',{maximumFractionDigits:2}):'—';
const parse=v=>root.IeltsStudyPlannerModel.timestamp(v,false),day=v=>root.IeltsStudyPlannerModel.dateKey(v);
const date=v=>new Date(v).toLocaleDateString('vi-VN',{timeZone:'Asia/Bangkok',day:'2-digit',month:'2-digit'});
function eventAt(e,end=false){const d=parse(e.date||e.lessonDate);if(d===null)return null;const m=String(end?e.endTime||'23:59':e.startTime||'00:00').match(/^(\d{1,2}):(\d{2})$/);if(!m||+m[1]>23||+m[2]>59)return null;return d+(+m[1]*60+ +m[2])*60000;}
function hasResult(a){return !a.dataConflict&&(a.components||[]).some(c=>!c.dataConflict&&(Number.isFinite(c.band)&&c.band>=0&&c.band<=9||Number.isFinite(c.raw)&&Number.isFinite(c.max)&&c.max>0&&c.raw>=0&&c.raw<=c.max));}
function scheduleModel({events=[],reminders=[],results=[],cancelled=[],now=Date.now(),assessmentKey}){
 const key=assessmentKey||((r)=>r.officialAssessmentKey||(r.assessmentFamily&&r.attempt?r.assessmentFamily+'|'+r.attempt:'')),completed=new Set(results.filter(hasResult).map(key).filter(Boolean)),seen=new Set();
 const lessons=events.filter(e=>{if(!e||e.cancelled||e.canceled||!['writing','speaking'].includes(e.skill))return false;const end=eventAt(e,true),at=eventAt(e);if(end===null||at===null||end<=now)return false;if(cancelled.some(c=>c.date===e.date&&(!c.startTime||c.startTime===e.startTime)&&(!c.skill||c.skill===e.skill)&&(!c.scheduleClassName||c.scheduleClassName===e.scheduleClassName)&&(!c.groupLabel||c.groupLabel===e.groupLabel)))return false;const id=[e.date,e.startTime,e.skill,e.scheduleClassName,e.groupLabel].join('|');if(seen.has(id))return false;seen.add(id);return true;}).sort((a,b)=>eventAt(a)-eventAt(b));
 const cutoff=parse(day(now))+15*DAY;const upcoming=reminders.filter(r=>{const at=parse(r.date);return at!==null&&at+DAY>now&&at<cutoff&&!completed.has(key(r));}).sort((a,b)=>parse(a.date)-parse(b.date));
 return {lessons,reminders:upcoming};
}
function mapLink(url){try{const u=new URL(url);return /^https?:$/.test(u.protocol)?'<a href="'+esc(u.href)+'" target="_blank" rel="noopener">Xem bản đồ ↗</a>':'';}catch(_){return '';}}
function schedule(model){return (root.Ielts48Master?.schedule(model)||'')+'<header class="section-head polish-schedule-heading"><p class="eyebrow">THỜI KHÓA BIỂU</p><h2>Lịch học</h2></header>'+ (model.reminders.length?'<section class="polish-upcoming" aria-label="Kiểm tra sắp diễn ra">'+model.reminders.map((r,i)=>'<article class="assessment-alert" data-assessment-upcoming="'+i+'"><span class="assessment-alert__badge">KIỂM TRA SẮP DIỄN RA</span><h3>'+esc(r.detail||r.program||'Bài kiểm tra')+'</h3><p>'+esc(r.date)+(r.groupLabel?' · '+esc(r.groupLabel):'')+'</p>'+(r.information?'<p>'+esc(r.information)+'</p>':'')+'</article>').join('')+'</section>':'')+
 '<div class="polish-schedule-grid">'+['writing','speaking'].map(skill=>{const rows=model.lessons.filter(e=>e.skill===skill);return '<section class="polish-schedule-lane"><header><span>'+skills[skill]+'</span><h3>'+(skill==='writing'?'Lịch cả lớp':'Lịch riêng của em')+'</h3></header>'+(rows.length?rows.map((e,i)=>'<article class="polish-lesson" data-assignment-id="schedule-'+esc([e.skill,e.date,e.startTime,e.scheduleClassName].join('-'))+'"><div><strong>'+esc(e.session||'Buổi học')+'</strong><span>'+esc(new Date(eventAt(e)).toLocaleDateString('vi-VN',{timeZone:'Asia/Bangkok',weekday:'long',day:'2-digit',month:'2-digit'}))+'</span></div><b>'+esc(e.startTime)+'–'+esc(e.endTime)+'</b><p>'+esc(e.groupLabel||e.scheduleClassName||'')+'</p><small>'+esc(e.location||'Chưa có địa điểm')+'</small>'+mapLink(e.mapUrl)+'</article>').join(''):'<p class="polish-no-lesson">Chưa có buổi học tiếp theo được công bố.</p>')+'</section>';}).join('')+'</div>';}
function trendModel(student,now=Date.now()){
 const rows=root.IeltsAcademicEvidence({actions:{profile:{student}}}).filter(r=>r.sourceAt>0&&r.sourceAt<=now&&!r.conflict),series=Object.keys(skills).map(skill=>{const points=rows.filter(r=>r.skill===skill).sort((a,b)=>a.sourceAt-b.sourceAt||a.key.localeCompare(b.key));return {skill,points,delta:points.length>=2?Math.round((points.at(-1).band-points[0].band)*100)/100:null};});
 return {series,rows,dates:[...new Set(rows.map(r=>r.sourceAt))].sort((a,b)=>a-b)};
}
function trend(student){const model=trendModel(student),available=model.series.filter(s=>s.points.length),dates=model.dates,small=typeof innerWidth==='number'&&innerWidth<=650,W=small?340:760,H=small?240:265,L=small?30:42,R=22,T=22,B=43,width=W-L-R,height=H-T-B,min=dates[0],max=dates.at(-1),x=at=>dates.length<=1?L+width/2:L+(at-min)/(max-min)*width,y=band=>T+height-band/9*height;
 let chart='';if(dates.length){chart='<svg class="polish-trend-svg" viewBox="0 0 '+W+' '+H+'" role="img" aria-label="Band kiểm tra theo thời gian"><desc>'+esc(available.map(s=>skills[s.skill]+': '+s.points.map(p=>p.sourceDate+' Band '+num(p.band)).join(', ')).join('; '))+'</desc>'+[0,3,6,9].map(v=>'<line x1="'+L+'" x2="'+(W-R)+'" y1="'+y(v)+'" y2="'+y(v)+'" stroke="#e0e8f2"/><text x="'+(L-12)+'" y="'+(y(v)+4)+'" text-anchor="end">'+v+'</text>').join('')+
 dates.map(at=>'<text x="'+x(at)+'" y="'+(H-17)+'" text-anchor="middle">'+esc(date(at))+'</text>').join('')+
 available.map(s=>(s.points.length>1?'<polyline class="polish-trend-line" fill="none" stroke="'+colors[s.skill]+'" stroke-width="3" points="'+s.points.map(p=>x(p.sourceAt)+','+y(p.band)).join(' ')+'"/>':'')+s.points.map(p=>'<circle cx="'+x(p.sourceAt)+'" cy="'+y(p.band)+'" r="5" fill="'+colors[s.skill]+'"><title>'+esc(skills[s.skill]+' · '+p.sourceDate+' · Band '+num(p.band))+'</title></circle>').join('')).join('')+'</svg>';}
 const comparables=available.filter(s=>s.delta!==null);return '<section class="polish-trend" id="ielts48-progress-trend"><header><p class="study-eyebrow">QUA CÁC LẦN KIỂM TRA</p><h2>Tiến bộ của em</h2></header>'+(available.length?chart+'<div class="polish-trend-legend">'+available.map(s=>'<span><i style="background:'+colors[s.skill]+'"></i>'+skills[s.skill]+' · '+s.points.length+' lần kiểm tra</span>').join('')+'</div>'+(comparables.length?'<div class="polish-growth">'+comparables.map(s=>'<div><strong>'+skills[s.skill]+'</strong><b class="'+(s.delta>0?'positive':s.delta<0?'negative':'')+'">'+(s.delta===null?'Chưa đủ 2 lần kiểm tra':s.delta>0?'📈 +'+num(s.delta)+' Band':s.delta<0?'Giảm '+num(-s.delta)+' Band':'Không đổi')+'</b></div>').join('')+'</div>':'')+'<p class="polish-trend-note">'+(comparables.length?'So với lần kiểm tra đầu tiên cùng kỹ năng.':'Chưa đủ hai lần kiểm tra cùng kỹ năng để tính mức tăng Band.')+'</p><details data-history-section="trend-scores"><summary>Xem mốc điểm</summary><div class="study-table-scroll"><table><thead><tr><th>Ngày kiểm tra</th><th>Kỹ năng</th><th>Band</th></tr></thead><tbody>'+model.rows.slice().sort((a,b)=>a.sourceAt-b.sourceAt||a.skill.localeCompare(b.skill)).map(p=>'<tr><td>'+esc(p.sourceDate)+'</td><td>'+skills[p.skill]+'</td><td>'+num(p.band)+'</td></tr>').join('')+'</tbody></table></div></details>':'<p>Chưa có điểm kiểm tra để vẽ biểu đồ.</p>')+'</section>';}
function install(o){o.wrap(()=>{const s=o.getState();if(!s.dashboard)return;const model=scheduleModel({events:o.events(),reminders:o.reminders(),results:s.student?.assessmentResults||[],cancelled:s.dashboard.cancelledLessonEvents||[],assessmentKey:o.assessmentKey});o.render(schedule(model));});let timer;window.addEventListener('resize',()=>{clearTimeout(timer);timer=setTimeout(()=>{if(o.getState().active==='overview')IeltsStableView.update(IeltsStableView.capture(),o.refreshResults);},150);});}
function updateWriting(host,html){let slot=host.querySelector('#ielts48-writing-overview');if(!slot){slot=document.createElement('section');slot.id='ielts48-writing-overview';root.Ielts48Grouped.protect(slot);host.appendChild(slot);}if(slot.__writingHtml===html)return;slot.__writingHtml=html;slot.innerHTML=html;}
root.Ielts48Polish={install,scheduleModel,schedule,trendModel,trend,eventAt,updateWriting};
})(globalThis);
